reversal.fixed_text:
assert!(self.char() == '{');
let start = self.pos();
let ast = match concat.asts.pop() {
    Some(ast) => ast,
    None => return Err(self.error(
        self.span(),
        ast::ErrorKind::RepetitionMissing,
    )),
};
match ast {
    Ast::Empty(_) | Ast::Flags(_) => return Err(self.error(
        self.span(),
        ast::ErrorKind::RepetitionMissing,
    )),
    _ => {}
}

